-- ============================================================================
-- DC10 - Rock Physics Beginner (Associate) goes deep.
--
-- Flips (rockphysics, beginner) onto the DC1 deep path by inserting its ACTIVE
-- academy_course_structures row, generated from the repo manifest
-- src/content/courses/rockphysics/beginner/manifest.json (the structure source
-- of truth; this file was emitted by a generator, not hand-typed), and
-- seeding the module quiz banks (15+15+15+15+15+15 questions) plus the
-- 42-question final exam bank. Answer keys live only here and in the
-- table (no client SELECT policies); the repo lesson content carries no
-- graded questions.
--
-- Every numeric question traces to the rockphysics teaching oracle and
-- reproduces the live NG8 Beginner capstone answer key: Batzle-Wang
-- brine, gas and live oil at 60 degC and 25 MPa, the Voigt-Reuss-Hill
-- 70/30 quartz-clay frame, and Wood's mixed pore fluid at Sw 0.8
-- (brine rho 1017.8249875, brine K 2.6978112899395996 GPa, gas K
-- 55.71865290286663 MPa, oil rho 777.0630099023522, frame K
-- 30.87940062475596 GPa, Wood K 257.3340919366766 MPa). The engine
-- fixtures are committed goldens dual-checked against bruges,
-- open_petro_elastic and rockphypy. That is the same pipeline
-- src/lib/rockphysicsTeaching.js drives and src/components/course/
-- panels/rockphysics/fluidLab.test.js pins.
--
-- Enrollment grandfathering: enforced_from defaults to now() on first
-- insert, so learners enrolled before this apply finish on the old path;
-- the ON CONFLICT update deliberately leaves enforced_from unchanged on
-- re-seeds. Re-seeding replaces the whole bank for this course-tier;
-- fine while there are no open attempts (open attempts pin question ids).
-- ============================================================================

values ('rockphysics', 'beginner', '{"modules":[{"key":"m01-rock-physics-and-the-seismic-bridge","title":"Rock Physics and the Seismic Bridge","lesson_keys":["l01-why-rock-physics","l02-the-ekene-sand-at-depth","l03-moduli-and-velocity","l04-the-beginner-workflow-map"]},{"key":"m02-reservoir-fluids","title":"Reservoir Fluids","lesson_keys":["l01-fluids-are-not-constants","l02-brine","l03-gas","l04-live-oil","l05-comparing-the-three"]},{"key":"m03-the-mineral-frame","title":"The Mineral Frame","lesson_keys":["l01-minerals-and-mixtures","l02-voigt-and-reuss","l03-the-vrh-average","l04-what-the-bound-spread-tells-you"]},{"key":"m04-mixing-the-pore-fluid","title":"Mixing the Pore Fluid","lesson_keys":["l01-woods-equation","l02-why-density-is-easy","l03-the-gas-effect","l04-reading-the-mix"]},{"key":"m05-how-conditions-change-the-answer","title":"How Conditions Change the Answer","lesson_keys":["l01-temperature","l02-pressure","l03-salinity-and-gas-gravity","l04-why-in-situ-conditions-matter"]},{"key":"m06-the-rock-physics-workflow","title":"The Rock Physics Workflow","lesson_keys":["l01-the-workflow-end-to-end","l02-quality-control","l03-the-capstone-walkthrough","l04-onward-to-professional"]}]}'::jsonb, 1)
